#!/usr/bin/python3

import pyrob.core as rob
from pyrob.tasks import check_filled_cells, find_cells_to_be_filled


class Task:
    CHECKS = 1

    def load_level(self, n):
        rob.set_field_size(9, 9)
        idx = 0
        if idx == 0:
            rob.set_cell_type(0, 4, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 3, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 5, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(2, 2, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(2, 6, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(3, 1, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(3, 7, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(4, 0, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(4, 8, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(5, 1, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(5, 7, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(6, 2, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(6, 6, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(7, 3, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(7, 5, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(8, 4, rob.CELL_TO_BE_FILLED)
            rob.set_parking_cell(4, 0)
            rob.goto(4, 0)

        self.cells_to_fill = find_cells_to_be_filled()

    def check_solution(self):
        return check_filled_cells(self.cells_to_fill) and rob.is_parking_point()
